<?php
require_once __DIR__.'/../../includes/staff/auth.php';require_permission('task.create');verify_csrf();$pdo=staff_db();$me=current_staff();if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("INSERT INTO tasks(title,description,assigned_to,assigned_by,priority,status,due_date) VALUES(?,?,?,?,?,'todo',?)")->execute([trim($_POST['title']),trim($_POST['description']),$_POST['assigned_to'],$me['id'],$_POST['priority'],$_POST['due_date']?:null]);staff_redirect('staff/admin/task-management.php');}$staff=$pdo->query("SELECT id,first_name,last_name FROM staff WHERE is_active=1 ORDER BY first_name")->fetchAll();$rows=$pdo->query("SELECT t.*,CONCAT(s.first_name,' ',COALESCE(s.last_name,'')) staff_name FROM tasks t LEFT JOIN staff s ON s.id=t.assigned_to ORDER BY t.created_at DESC")->fetchAll();$pageTitle='Task Management';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Management</p><h1>Task management</h1></div></div><div class="split-grid"><section class="staff-panel"><h2>Assign task</h2><form method="post"><?= csrf_field() ?><label>Title<input name="title" required></label><label>Assign to<select name="assigned_to"><?php foreach($staff as $s):?><option value="<?= $s['id'] ?>"><?= h(trim($s['first_name'].' '.$s['last_name'])) ?></option><?php endforeach;?></select></label><label>Priority<select name="priority"><option>low</option><option selected>normal</option><option>high</option><option>urgent</option></select></label><label>Due<input type="datetime-local" name="due_date"></label><label>Description<textarea name="description"></textarea></label><button class="btn primary">Assign task</button></form></section><section class="staff-panel table-panel"><table><thead><tr><th>Task</th><th>Staff</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= h($r['title']) ?></td><td><?= h($r['staff_name']?:'—') ?></td><td><?= h($r['status']) ?></td></tr><?php endforeach;?></tbody></table></section></div></main><?php require __DIR__.'/../../includes/staff/footer.php';?>
